pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(newOwner != address(0));

        vm.prank(actor);
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.transferOwnership.selector, newOwner)
        );

        // General rule: a non-owner can never change ownership.
        // Correct contract: call reverts (ok == false), owner unchanged.
        // Buggy contract: some caller (e.g. the fuzzer's actor) succeeds
        // (ok == true) and ownership moves to newOwner, breaking the rule.
        assertTrue(!ok && c.owner() != newOwner);
    }
}

