contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount > 0 && amount <= type(uint216).max, "bad amount");
        // register the reward token (this test contract acts as the token)
        c.addReward(address(this));
        // become the reward distributor
        c.setRewardDistributor(address(this));
        // as distributor, notify rewards; must not revert on the original contract
        c.notifyRewardAmount(address(this), amount);
        // the notify must have taken effect
        assert(
            c.rewardData(address(this)).rewardRate == uint216(amount / c.DURATION()) &&
            c.rewardPeriodFinish(address(this)) == uint40(block.timestamp + c.DURATION())
        );
    }
    // minimal ERC20-ish token behavior so SafeERC20 calls from C succeed
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }
    receive() external payable {}
}

